"""Audit and report the bounded recovery round without rewriting old results."""
import gzip,json,hashlib,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];OUT=ROOT/'docs/research/strategy-recovery-20261127'
def load(p):return json.loads(p.read_text())
def write(p,d):p.write_text(json.dumps(d,indent=2,allow_nan=False)+'\n')
def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','|'+'|'.join(['---']*len(headers))+'|']+['| '+' | '.join(str(v) for v in r)+' |' for r in rows])
def num(v):return '—' if v is None else f'{v:.2f}'
def audit(d):
    for r in d['results']:
        k=f"{r['lineup']}:{r['capital']:g}"
        if abs(r['final_equity']-r['capital']-sum(b['net'] for b in d['closed_baskets'][k]))>1e-5:raise ValueError('CASH_AUDIT')
        if sum(f['entry']==0 for f in d['fills'][k])!=r['individual_orders']:raise ValueError('FILL_AUDIT')

def main():
    placements=load(OUT/'placements.json');simple=load(OUT/'simple-summary.json');paired=[];audits=0
    for name in ('baseline','strategy-exits','opening','full-exits','orb-runtime','orb-stress'):
        p=ROOT/f'.tmp/recovery-{name}.json'
        if not p.exists():continue
        d=load(p);audit(d);audits+=len(d['results'])
        (OUT/f'{name}-receipts.json.gz').write_bytes(gzip.compress(p.read_bytes(),mtime=0))
        paired.append(dict(arm=name,sessions=d['sessions'],assumptions=d['assumptions'],source_sha256=d['archive_sha256'],runtime_sha256=d['strategy_file_sha256']['gold_turbo/runtime.py'],results=d['results']))
    native=json.loads(gzip.decompress((OUT/'simple-receipts.json.gz').read_bytes()))
    for r in native['result']['results']:
        if abs(r['endingBalance']-r['arm']['capital']-sum(t[6] for t in r['trades']))>1e-6:raise ValueError('SIMPLE_CASH_AUDIT')
    audits+=len(native['result']['results'])
    write(OUT/'recovery-summary.json',dict(schema='strategy-recovery/v1',lineups=placements['lineups'],paired=paired,cash_audited_accounts=audits,limits='Known October development comparisons. Parameter definitions frozen before each bounded experiment. No pristine holdout, exchange-native compilation, paid/live activation or Prop rule changes.',simple_cases=len(native['result']['results'])))
    lines=['# HashiBot strategy recovery and wiring — 27 November 2026','','## Exact customer placement','','All 21 decisions are in `DECISIONS.md` and `placements.json`. No configuration was deleted. Updated defaults flow through existing account onboarding and Admin preset assignment, account selection shortcuts, VIP publication allowlist and Browser Backtest Lab. Existing saved customer choices are not silently migrated. No provider activation was performed.','',''+table(['Customer mode','Exact default strategy IDs'],[[mode,', '.join(ids)] for mode,ids in placements['lineups'].items()]),'','Paused/LTC and thin-edge compression/sweep setups remain in explicitly named Admin comparison presets. Prop shortcuts are restricted to the curated two-Forex roster; the all-retained comparison remains an explicit Admin override. No Personal growth risk profile, drawdown bound, news rule or entitlement gate was transferred to Prop.','','## Engineering change','','Added a validated profit-exit choice from Admin configuration through scoped demo lease to local basket construction. STRATEGY_EXITS removes the shared basket equity-profit target and basket soft profit trail for Micro/Momentum/Range/Trend; their own targets, partial exits and trailing remain active. Hard basket loss, account loss, original risk, broker stops, news, margin and maximum holding controls remain active. The flagship retains its coordinated basket profit management. Existing open baskets retain their original immutable configuration through restart. Baseline EQUITY_TARGET remains the default unless the operator explicitly chooses the alternative.','','## Paired local-runtime development comparison','','Same three known sessions (6, 14, 22 October), 08–16 UTC; $500/$25,000 reset accounts, fixed 1% research decision budget, 15% daily/60% peak/50% entry margin limits. Every original quote checks broker stops; local decisions use a 5-second replay cadence. Costs: observed spread, $3.50/lot/side, $0.02/side slippage. Zero order latency and clear-news scenarios are limitations. These are paired tests, not month-long returns or production-cadence qualification.','',''+table(['Arm','Lineup','Capital','Return %','DD %','Baskets','Orders'],[[a['arm'],r['lineup'],r['capital'],num(r['net_return_pct']),num(r['maximum_drawdown_pct']),r['independent_baskets'],r['individual_orders']] for a in paired if a['arm'] not in ('full-exits','orb-runtime','orb-stress') for r in a['results']]),'']
    full=next((a for a in paired if a['arm']=='full-exits'),None)
    if full:
        old=load(ROOT/'docs/research/personal-edge-20261127/turbo-corrected-summary.json')['results']
        lines+=['## Full October selected-session confirmation','','All 22 weekdays, 08–16 UTC, same risk/capital/cost/cadence assumptions and retained quote archive as the prior full-month baseline. Compare native strategy profit handling with the preserved equity-target baseline. Entries remain unchanged; the optional simple Momentum models are disabled. These are selected sessions, not continuous 24-hour monthly accounts. Source versions differ by tested profit-exit support and safe pending-margin accounting; source hashes and receipts are retained.','',''+table(['Lineup','Capital','Baseline return %','Strategy exits return %','Baseline DD %','Strategy exits DD %','Baskets'],[[r['lineup'],r['capital'],num(next(q['net_return_pct'] for q in old if q['lineup']==r['lineup'] and q['capital']==r['capital'] and q['risk_pct']==1)),num(r['net_return_pct']),num(next(q['maximum_drawdown_pct'] for q in old if q['lineup']==r['lineup'] and q['capital']==r['capital'] and q['risk_pct']==1)),num(r['maximum_drawdown_pct']),r['independent_baskets']] for r in full['results']]),'','Decision: reject strategy-specific profit handling as the new default. At $500, Range deteriorated from -11.65% to -14.11%, Trend from -0.57% to -1.55%, and adaptive from -23.94% to -25.02%. Micro improved to -9.44% but still lost. The $25,000 Trend arm earned only +0.31% with 9.82% drawdown, insufficient for promotion. The new mode remains an explicit demo comparison option, with baseline default and hard protections preserved.']
    orb=[a for a in paired if a['arm'] in ('orb-runtime','orb-stress')]
    if len(orb)==2:
        lines+=['','## Opening range through the actual local manager at 200 ms','','All 22 October weekdays, 13–15 UTC, covering every defined October New York opening-range entry and its 15-minute maximum holding time. $25,000, experimental fixed 1% decision risk, 15% daily / 60% peak / 50% entry-margin research allowance; costs as above, adverse slippage $0.02 base / $0.05 stress. One original quote stream per run, observed bid/ask stops, reconciled basket decisions, strategy partial exits/trailing and account controls. This is the real local decision/management code on a fake historical terminal: immediate order response, no native broker partial-fill or latency qualification.','',''+table(['Case','Return %','DD %','Baskets','Orders','Win %','PF','Holding min','After $100 fee $'],[[a['arm'],num(r['net_return_pct']),num(r['maximum_drawdown_pct']),r['independent_baskets'],r['individual_orders'],num(r['win_rate_pct']),num(r['profit_factor']),num(r['average_holding_minutes']),num(r['subscription_adjusted_net_at_100_usd'])] for a in orb for r in a['results']]),'','Decision: expose SESSION_BREAKOUT as an explicit Admin demo comparison for standalone Momentum, with original baseline preserved. It increases participation to 45 baskets and remains a scalp. The stressed PF near 1.08 and 8.93% drawdown are too weak for promotion to a customer default or Prop roster. This does not meet the aggressive small-account Turbo growth objective.','', 'The modeled 1% lease is isolated research authorization. Current production leases and capital-band caps remain conservative; selecting the model in Admin does not grant 1% risk on a $25,000 account. The new source-aware continuation arbitration mapping is functionally tested; no new adaptive profitability claim is made. The earlier paired opening arm used its archived source version.','']
    lines+=['','## Two simpler, published-concept challengers','','Frozen models share the actual local `simple_intraday.py` entry functions and are optional Momentum configuration variants, preserving the 21-ID catalogue and the original default. New York opening-range breakout uses an observed 15-minute box; the other model uses a simple impulse/pullback/reclaim. Both use ATR scaling, 1.5R gross targets and strict 10–15 minute holds. No indicator voting stack or optimization sweep. US equity publications are concept sources, not verification of these Gold adaptations. Definitions and source URLs are in `simple-protocol.json`.','','Independent C++ execution screening used all 5,910,062 retained October bid/ask ticks, 200 ms base delay / 500 ms stress delay, observed spreads, commission, adverse slippage, volume floors and a 20% entry-margin budget. It is not the full Python/runtime execution manager. The original 96 accounts use qualification 1.5% daily / 8% peak limits. A separate 24-case opening-range comparison uses the existing Personal STANDARD 4% daily / 18% peak limits at unchanged 1% decision risk, explicitly fixed sizing rather than full dynamic House-Money. Both differ from the paired local experiment. Chronological halves are known development periods, not an untouched holdout.','',''+table(['Model / period','Capital','Risk %','Stress','Return %','DD %','Decisions','PF'],[[r['arm']['family'],r['arm']['capital'],r['arm']['risk'],r['arm']['stress'],num(r['returnPct']),num(r['drawdownPct']),r['closedTrades'],num(r['profitFactor'])] for r in simple['result']['results'] if r['arm']['capital'] in (500,25000) and (r['arm']['family'].endswith(':whole') or (r['arm']['capital']==25000 and not r['arm']['stress']))]),'','Decision: reject SIMPLE_PULLBACK as a replacement; it lost in both chronological halves. Keep SESSION_BREAKOUT as a comparison candidate only: the $25,000 0.25% whole-period screen was +1.12% (+1.11% stress) but its earlier half lost, its 1% whole-period account lost, and its local-runtime opening arm did not beat the original combination. The additional fixed-1% Personal STANDARD-limit opening screen returned +4.32% (+3.92% stress) at $25,000, with 6.99% drawdown, 36 decisions and PF 1.25. Its earlier half lost -2.56% and later reset half gained +6.95%. At $500 it returned +2.43% (+0.38% stress). These results motivate the separate actual-runtime check; they do not override the local-runtime evidence or automatically promote a default. A small profitable model at $25,000 does not establish a viable $100/$500 offering; minimum volume blocked the 0.25% small-account cases.','','## Verification and operating consequences','','Targeted tests cover all 21 placements, default/alternative separation, current 1,159-trade retention, Prop and live isolation, source-bound lease controls, new exit-mode validation, original basket settings across restart, hard-loss enforcement, causal long/short model geometry, DST session handling and duplicate admission. Targeted TSX bundles compiled; no broad repository suite ran. Per-test counts and exact account cash checks are in `verification.json`.','','Existing Crypto trend is the selected Personal core; optional alternatives and the updated eight-source VIP allowlist are wired through existing interfaces. These changes do not turn the earlier six-family research router into production Account Brain parity and do not promise its simulated return. Forex/Gold and Prop defaults are explicit curation from existing evidence; fresh FX entry validation and firm-specific outcome probabilities remain outstanding.','','All five Turbo engines retain their original scalp role, IDs and comparison baselines. Failed replacements remain outside defaults. Further improvement must beat these receipts on subsequent chronological market periods and production cadence. The full customer profitability goal has not been established by a label or selection change.','']
    (OUT/'RECOVERY.md').write_text('\n'.join(lines))
    counts={}
    for name,path in [('python','/tmp/recovery-gold-tests.log'),('typescript','/tmp/recovery-typescript-tests.log'),('replay','/tmp/recovery-replay-tests.log')]:
        s=Path(path).read_text();m=re.search(r'tests (\d+)' if name=='typescript' else r'Ran (\d+) tests',s);counts[name]=int(m[1]);
        if ('fail 0' if name=='typescript' else 'OK') not in s:raise ValueError('TEST_FAILURE')
    write(OUT/'verification.json',dict(tests=counts,cash_audited_accounts=audits,simple_accounts=len(native['result']['results']),paired_accounts=audits-len(native['result']['results']),catalogue_ids=len(placements['rows']),ui_bundles_compiled=['AccountStrategySelection','GoldTurboControls','BrowserLedgerLab'],paid_live_activated=False,existing_accounts_silently_reassigned=False))
    print('Audited accounts',audits,'tests',counts,'full October complete',full is not None)

if __name__=='__main__':main()
